DATA_FILE = Path(__file__).resolve().parents[2] / "data" / "products_full.json"


def gallery_from_item(item):
    """Gambar tambahan dari data Shopee: tanpa gambar utama, tanpa duplikat, maks. 8."""
    cover = item.get("cover_image") or ""
    seen, result = {cover}, []
    for url in item.get("images") or []:
        if url and url not in seen:
            seen.add(url)
            result.append(url)
    return result[:8]


def fill_images(apps, schema_editor):
    Product = apps.get_model("store", "Product")
    if not DATA_FILE.exists():
        return
    try:
        items = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    except ValueError:
        return
    for item in items:
        gallery = gallery_from_item(item)
        if item.get("id") and gallery:
            Product.objects.filter(pk=item["id"], images=[]).update(images=gallery)


